"""Independent checks for the C++ TLP target (developer tool, not a generator).

Usage: python tests/evaluate.py build/tlp_cli
Validates schemas, compares the compiled plan against an independently written
reference SQL on original and mutated data, and reports the public diversity
metrics from docs/contract.md.
"""
import json
import random
import sqlite3
import subprocess
import sys
from collections import Counter, defaultdict

CLI = sys.argv[1]
CMP = {"eq": "=", "ne": "<>", "lt": "<", "le": "<=", "gt": ">", "ge": ">="}
AGGS = {"count", "sum", "avg", "min", "max"}
LEGACY = {"count", "sum", "avg", "min", "max"}


def run(requests):
    out = subprocess.run([CLI], input="".join(json.dumps(r) + "\n" for r in requests),
                         text=True, capture_output=True, check=True).stdout
    return [json.loads(l) for l in out.splitlines()]


# ---------------- schema validation ----------------
class Invalid(Exception):
    pass


def need(ok, msg):
    if not ok:
        raise Invalid(msg)


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def kind(e, stage, keys, source, depth, in_agg=False):
    """Returns 'num', 'scalar' or 'pred'. stage: 'row' or 'group'."""
    need(depth <= 6, "too deep")
    need(isinstance(e, list) and e and isinstance(e[0], str), "malformed")
    if stage == "group" and not in_agg and any(e == k for k in keys):
        return kind(e, "row", [], source, depth)  # complete group key
    op = e[0]
    if op == "col":
        need(len(e) == 3 and e[1] in ("t", "u") and e[2] in ("id", "k", "v", "tag"), "col")
        need(not (source == "single" and e[1] == "u"), "u in single")
        need(stage == "row" or in_agg, "bare column at group stage")
        return "scalar" if e[2] == "tag" else "num"
    if op == "lit":
        need(len(e) == 2, "lit")
        v = e[1]
        if v is None:
            return "null"
        if is_int(v):
            need(-1000 <= v <= 1000, "lit bound")
            return "num"
        need(isinstance(v, str) and len(v) <= 32, "lit str")
        return "scalar"
    if op in ("add", "sub"):
        need(len(e) == 3, "arity")
        for x in e[1:]:
            need(kind(x, stage, keys, source, depth + 1, in_agg) == "num", "arith non-numeric")
        return "num"
    if op in CMP:
        need(len(e) == 3, "arity")
        for x in e[1:]:
            need(kind(x, stage, keys, source, depth + 1, in_agg) != "pred", "cmp of pred")
        return "pred"
    if op in ("and", "or", "not"):
        need(len(e) == (2 if op == "not" else 3), "arity")
        for x in e[1:]:
            need(kind(x, stage, keys, source, depth + 1, in_agg) == "pred", "bool of non-pred")
        return "pred"
    if op == "isnull":
        need(len(e) == 2, "arity")
        kind(e[1], stage, keys, source, depth + 1, in_agg)
        return "pred"
    if op == "agg":
        need(stage == "group" and not in_agg, "agg misplaced")
        need(len(e) == 3 and e[1] in AGGS, "agg")
        if e[2] is None:
            need(e[1] == "count", "star")
        else:
            need(kind(e[2], "row", [], source, depth + 1, True) == "num", "agg arg")
        return "num"
    raise Invalid("unknown op " + op)


def validate(c):
    need(set(c) == {"version", "tables", "source", "predicate", "where", "mode", "select",
                    "value", "group_by"}, "keys")
    need(c["version"] == 1, "version")
    need(set(c["tables"]) == {"t", "u"}, "tables")
    for rows in c["tables"].values():
        need(len(rows) <= 32, "rows")
        for r in rows:
            need(len(r) == 4, "row width")
            for x in r[:3]:
                need(x is None or (is_int(x) and -1000 <= x <= 1000), "cell")
            need(r[3] is None or (isinstance(r[3], str) and len(r[3]) <= 32), "tag")
    src, mode = c["source"], c["mode"]
    need(src in ("single", "inner", "left"), "source")
    gb = c["group_by"]
    need(isinstance(gb, list) and len(gb) <= 2, "group_by")
    for g in gb:
        need(kind(g, "row", [], src, 1) not in ("pred",), "group key pred")
    if c["where"] is not None:
        need(kind(c["where"], "row", [], src, 1) == "pred", "where")
    sel = c["select"]
    if mode in ("rows", "distinct"):
        need(1 <= len(sel) <= 3 and not gb and c["value"] is None, "rows shape")
        for s in sel:
            need(kind(s, "row", [], src, 1) != "pred", "select pred")
        need(kind(c["predicate"], "row", [], src, 1) == "pred", "pred")
    elif mode == "group":
        need(gb and sel == gb and c["value"] is None, "group shape")
        need(kind(c["predicate"], "row", [], src, 1) == "pred", "pred")
    elif mode == "having":
        need(1 <= len(sel) <= 3 and c["value"] is None, "having shape")
        for s in sel:
            need(kind(s, "group", gb, src, 1) != "pred", "select pred")
        if not gb:
            need("agg" in json.dumps(sel), "no aggregate")
        need(kind(c["predicate"], "group", gb, src, 1) == "pred", "pred")
    elif mode in LEGACY:
        need(sel == [], "select")
        if c["value"] is None:
            need(mode == "count", "value")
        else:
            need(kind(c["value"], "row", [], src, 1) == "num", "value numeric")
        need(kind(c["predicate"], "row", [], src, 1) == "pred", "pred")
    else:
        raise Invalid("mode")


# ---------------- independent reference SQL ----------------
def lit_sql(v):
    if v is None:
        return "NULL"
    if is_int(v):
        return "(%d)" % v
    return "CAST(X'%s' AS TEXT)" % v.encode().hex() if v else "''"


def sql(e):
    op = e[0]
    if op == "col":
        return "%s.%s" % (e[1], e[2])
    if op == "lit":
        return lit_sql(e[1])
    if op == "add":
        return "(%s+%s)" % (sql(e[1]), sql(e[2]))
    if op == "sub":
        return "(%s-%s)" % (sql(e[1]), sql(e[2]))
    if op in CMP:
        return "(%s %s %s)" % (sql(e[1]), CMP[op], sql(e[2]))
    if op in ("and", "or"):
        return "(%s %s %s)" % (sql(e[1]), op.upper(), sql(e[2]))
    if op == "not":
        return "(NOT %s)" % sql(e[1])
    if op == "isnull":
        return "(%s IS NULL)" % sql(e[1])
    if op == "agg":
        return "%s(%s)" % (e[1], "*" if e[2] is None else sql(e[2]))
    raise ValueError(op)


FROM = {"single": "t", "inner": "t JOIN u ON t.k=u.k", "left": "t LEFT JOIN u ON t.k=u.k"}


def reference(c):
    mode, gb = c["mode"], c["group_by"]
    w = sql(c["where"]) if c["where"] is not None else None
    p = sql(c["predicate"])
    filters = [None, p, "NOT %s" % p, "(%s) IS NULL" % p]
    out = []
    for i, f in enumerate(filters):
        if mode in ("rows", "distinct", "having"):
            cols = [sql(s) for s in c["select"]]
        elif mode == "group":
            cols = [sql(g) for g in gb]
        else:
            arg = "*" if c["value"] is None else sql(c["value"])
            cols = [sql(g) for g in gb]
            if i and mode in ("sum", "avg"):
                cols += ["sum(%s)" % arg, "count(%s)" % arg]
            else:
                cols.append("%s(%s)" % (mode, arg))
        q = "SELECT %s%s FROM %s" % ("DISTINCT " if mode == "distinct" else "", ",".join(cols),
                                     FROM[c["source"]])
        conds = [x for x in [w, f if mode != "having" else None] if x]
        if conds:
            q += " WHERE " + " AND ".join("(%s)" % x for x in conds)
        if gb and mode not in ("rows", "distinct"):
            q += " GROUP BY " + ",".join(sql(g) for g in gb)
        if mode == "having" and f:
            q += " HAVING " + f
        out.append(q)
    return out


def make_db(tables):
    db = sqlite3.connect(":memory:")
    for name in ("t", "u"):
        db.execute("CREATE TABLE %s(id INTEGER,k INTEGER,v INTEGER,tag TEXT)" % name)
        db.executemany("INSERT INTO %s VALUES(?,?,?,?)" % name, [tuple(r) for r in tables[name]])
    return db


def canon(rows):
    def cell(x):
        return (type(x).__name__, x)
    return sorted(repr([cell(x) for x in r]) for r in rows)


def mutate(tables, rnd):
    new = {}
    for name, rows in tables.items():
        rows = [list(r) for r in rows]
        for r in rows:
            for j in range(3):
                if rnd.random() < 0.3:
                    r[j] = rnd.choice([None, rnd.randint(-5, 5)])
            if rnd.random() < 0.2:
                r[3] = rnd.choice([None, "a", "b", "q'", ""])
        if rnd.random() < 0.5:
            rows.append([rnd.choice([None, 1, 2]), rnd.randint(-2, 2), rnd.randint(-3, 3), "a"])
        new[name] = rows
    return new


def semantic(c, plan, rnd):
    ref = reference(c)
    mine = [plan["base"]] + plan["parts"]
    for tables in (c["tables"], mutate(c["tables"], rnd), mutate(c["tables"], rnd)):
        db = make_db(tables)
        for q, r in zip(mine, ref):
            a = db.execute(q["sql"], q["params"]).fetchall()
            b = db.execute(r).fetchall()
            if canon(a) != canon(b):
                return False, (q, r, a, b)
    return True, None


# ---------------- fingerprints ----------------
def strip(e, cols=True):
    if isinstance(e, list):
        if e and e[0] == "lit":
            return ["lit"]
        if e and e[0] == "col":
            return ["col", e[1], e[2]] if cols else ["col"]
        return [strip(x, cols) for x in e]
    return e


def fingerprint(c, cols=True):
    d = {k: strip(v, cols) for k, v in c.items() if k not in ("tables", "version")}
    return json.dumps(d, sort_keys=True)


def depth(e):
    if not isinstance(e, list) or not e or e[0] in ("col", "lit"):
        return 1
    return 1 + max(depth(x) for x in e[1:] if isinstance(x, list)) if any(isinstance(x, list) for x in e[1:]) else 1


def ops(e, acc, stage):
    if isinstance(e, list) and e and isinstance(e[0], str):
        acc[(e[0], stage)] += 1
        if e[0] == "agg":
            acc[("agg:" + e[1] + (":star" if e[2] is None else ":expr"), stage)] += 1
        if e[0] == "col":
            acc[("table:" + e[1], stage)] += 1
            acc[("column:" + e[2], stage)] += 1
        if e[0] != "lit":
            for x in e[1:]:
                ops(x, acc, stage)


def main():
    rnd = random.Random(20261022)
    inputs = [bytes(rnd.getrandbits(8) for _ in range(rnd.randint(16, 512))) for _ in range(1024)]
    boundary = [b"", b"\0", b"\xff" * 512, bytes(range(256)) * 2, b"\0" * 513, b"A" * 1000]
    answers = run([{"op": "inspect", "hex": b.hex()} for b in inputs + boundary])
    bad = 0
    sem_bad = 0
    for a in answers:
        try:
            validate(a["case"])
        except Invalid as e:
            bad += 1
            if bad < 5:
                print("INVALID", e, json.dumps(a["case"])[:400])
        assert a["result"]["equivalent"] and a["result"]["calls"] == 4
        ok, info = semantic(a["case"], a["plan"], rnd)
        if not ok:
            sem_bad += 1
            if sem_bad < 5:
                print("SEMANTIC MISMATCH", info)
    print("schema invalid:", bad, "semantic mismatches:", sem_bad, "of", len(answers))
    answers = answers[:1024]
    cases = [a["case"] for a in answers]
    modes = Counter(c["mode"] for c in cases)
    print("modes", dict(modes))
    print("sources", dict(Counter(c["source"] for c in cases)))
    print("existing where", sum(c["where"] is not None for c in cases))
    print("grouped legacy", sum(c["mode"] in LEGACY and bool(c["group_by"]) for c in cases))
    print("distinct cases", len({json.dumps(c, sort_keys=True) for c in cases}))
    print("distinct dbs", len({json.dumps(c["tables"], sort_keys=True) for c in cases}))
    print("structural fp", len({fingerprint(c) for c in cases}))
    print("topology fp", len({fingerprint(c, False) for c in cases}))
    per = defaultdict(set)
    for c in cases:
        per[c["mode"]].add(fingerprint(c, False))
    print("topology per mode", {m: len(s) for m, s in per.items()})

    # occupancy (independently computed)
    all3 = nonempty = empty_row = overlap = dup_having = allnull = 0
    for c in cases:
        db = make_db(c["tables"])
        ref = reference(c)
        base = db.execute(ref[0]).fetchall()
        nonempty += bool(base)
        p = sql(c["predicate"])
        w = sql(c["where"]) if c["where"] else "1"
        if c["mode"] == "having":
            gb = ",".join(sql(g) for g in c["group_by"])
            counts = []
            for f in (p, "NOT " + p, "(%s) IS NULL" % p):
                q = "SELECT 1 FROM %s WHERE %s %s HAVING %s" % (
                    FROM[c["source"]], w, ("GROUP BY " + gb) if gb else "", f)
                counts.append(len(db.execute(q).fetchall()))
            dup_having += len(base) != len(set(base))
        else:
            counts = [db.execute("SELECT count(*) FROM %s WHERE (%s) AND (%s)" % (FROM[c["source"]], w, f)).fetchone()[0]
                      for f in (p, "NOT " + p, "(%s) IS NULL" % p)]
            rowcount = db.execute("SELECT count(*) FROM %s WHERE %s" % (FROM[c["source"]], w)).fetchone()[0]
            empty_row += rowcount == 0
        all3 += all(counts)
        if c["mode"] == "group":
            parts = [set(db.execute(q).fetchall()) for q in ref[1:]]
            overlap += any(parts[i] & parts[j] for i in range(3) for j in range(i + 1, 3))
        if c["mode"] in ("sum", "avg", "min", "max"):
            vals = db.execute("SELECT %s FROM %s WHERE %s" % (sql(c["value"]), FROM[c["source"]], w)).fetchall()
            allnull += bool(vals) and all(v[0] is None for v in vals)
    print("all3 partitions", all3, "nonempty base", nonempty, "empty row-stage", empty_row,
          "group overlap", overlap, "having dup", dup_having, "all-null agg input", allnull)

    acc = Counter()
    deep = 0
    for c in cases:
        hv = c["mode"] == "having"
        ops(c["predicate"], acc, "group" if hv else "row")
        deep += depth(c["predicate"]) >= 3
        if c["where"]:
            ops(c["where"], acc, "row")
            deep += depth(c["where"]) >= 3
        for s in c["select"]:
            ops(s, acc, "group" if hv else "row")
        for g in c["group_by"]:
            ops(g, acc, "row")
        if c["value"] is not None:
            ops(c["value"], acc, "row")
    print("depth>=3 predicates", deep)
    print("count(*) legacy", sum(c["mode"] == "count" and c["value"] is None for c in cases),
          "count(expr) legacy", sum(c["mode"] == "count" and c["value"] is not None for c in cases))
    print("ops", dict(sorted((("%s@%s" % k), v) for k, v in acc.items())))

    # counterfactual quarter replacement
    base_inputs = [bytes(rnd.getrandbits(8) for _ in range(128)) for _ in range(64)]
    reqs = [{"op": "inspect", "hex": b.hex()} for b in base_inputs]
    variants = []
    for b in base_inputs:
        for q in range(4):
            nb = bytearray(b)
            nb[q * 32:(q + 1) * 32] = bytes(rnd.getrandbits(8) for _ in range(32))
            variants.append(bytes(nb))
    res = run(reqs + [{"op": "inspect", "hex": v.hex()} for v in variants])
    orig, var = res[:64], res[64:]
    for q in range(4):
        ch = topo = 0
        for i in range(64):
            a, b = orig[i]["case"], var[i * 4 + q]["case"]
            ch += a != b
            topo += fingerprint(a, False) != fingerprint(b, False)
        print("quarter", q, "case changes", ch, "topology changes", topo)
    again = run(reqs[:16])
    assert all(x == y for x, y in zip(again, orig[:16])), "nondeterministic"
    print("deterministic ok")


main()

"""Independent checks for the C++ TLP target (developer tool, not a generator).

Usage: python3 tests/evaluate.py build/tlp_cli
Validates schemas, compares the compiled plan against independently written
reference SQL on original and mutated data, and reports the public diversity
metrics from docs/contract.md.
"""
import json
import random
import sqlite3
import subprocess
import sys
from collections import Counter, defaultdict

CLI = sys.argv[1]
CMP = {"eq": "=", "ne": "<>", "lt": "<", "le": "<=", "gt": ">", "ge": ">="}
AGGS = {"count", "sum", "avg", "min", "max"}
LEGACY = AGGS


def run(requests):
    out = subprocess.run([CLI], input="".join(json.dumps(r) + "\n" for r in requests),
                         text=True, capture_output=True, check=True).stdout
    return [json.loads(line) for line in out.splitlines()]


class Invalid(Exception):
    pass


def need(ok, msg):
    if not ok:
        raise Invalid(msg)


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def kind(e, stage, keys, source, depth, in_agg=False):
    """Returns 'num', 'scalar', 'null' or 'pred'."""
    need(depth <= 6, "too deep")
    need(isinstance(e, list) and e and isinstance(e[0], str), "malformed")
    if stage == "group" and not in_agg and any(e == k for k in keys):
        return kind(e, "row", [], source, depth)
    op = e[0]
    if op == "col":
        need(len(e) == 3 and e[1] in ("t", "u") and e[2] in ("id", "k", "v", "tag"), "col")
        need(not (source == "single" and e[1] == "u"), "u in single")
        need(stage == "row" or in_agg, "bare column at group stage")
        return "scalar" if e[2] == "tag" else "num"
    if op == "lit":
        need(len(e) == 2, "lit")
        v = e[1]
        if v is None:
            return "null"
        if is_int(v):
            need(-1000 <= v <= 1000, "lit bound")
            return "num"
        need(isinstance(v, str) and len(v) <= 32, "lit str")
        return "scalar"
    if op in ("add", "sub"):
        need(len(e) == 3, "arity")
        for x in e[1:]:
            need(kind(x, stage, keys, source, depth + 1, in_agg) == "num", "arith non-numeric")
        return "num"
    if op in CMP:
        need(len(e) == 3, "arity")
        for x in e[1:]:
            need(kind(x, stage, keys, source, depth + 1, in_agg) != "pred", "cmp of pred")
        return "pred"
    if op in ("and", "or", "not"):
        need(len(e) == (2 if op == "not" else 3), "arity")
        for x in e[1:]:
            need(kind(x, stage, keys, source, depth + 1, in_agg) == "pred", "bool of non-pred")
        return "pred"
    if op == "isnull":
        need(len(e) == 2, "arity")
        kind(e[1], stage, keys, source, depth + 1, in_agg)
        return "pred"
    if op == "agg":
        need(stage == "group" and not in_agg, "agg misplaced")
        need(len(e) == 3 and e[1] in AGGS, "agg")
        if e[2] is None:
            need(e[1] == "count", "star")
        else:
            need(kind(e[2], "row", [], source, depth + 1, True) == "num", "agg arg")
        return "num"
    raise Invalid("unknown op " + op)


def validate(c):
    need(set(c) == {"version", "tables", "source", "predicate", "where", "mode", "select",
                    "value", "group_by"}, "keys")
    need(c["version"] == 1, "version")
    need(set(c["tables"]) == {"t", "u"}, "tables")
    for rows in c["tables"].values():
        need(len(rows) <= 32, "rows")
        for r in rows:
            need(len(r) == 4, "row width")
            for x in r[:3]:
                need(x is None or (is_int(x) and -1000 <= x <= 1000), "cell")
            need(r[3] is None or (isinstance(r[3], str) and len(r[3]) <= 32), "tag")
    src, mode = c["source"], c["mode"]
    need(src in ("single", "inner", "left"), "source")
    gb = c["group_by"]
    need(isinstance(gb, list) and len(gb) <= 2, "group_by")
    for g in gb:
        need(kind(g, "row", [], src, 1) in ("num", "scalar"), "group key")
    if c["where"] is not None:
        need(kind(c["where"], "row", [], src, 1) == "pred", "where")
    sel = c["select"]
    if mode in ("rows", "distinct"):
        need(1 <= len(sel) <= 3 and not gb and c["value"] is None, "rows shape")
        for s in sel:
            need(kind(s, "row", [], src, 1) != "pred", "select pred")
        need(kind(c["predicate"], "row", [], src, 1) == "pred", "pred")
    elif mode == "group":
        need(gb and sel == gb and c["value"] is None, "group shape")
        need(kind(c["predicate"], "row", [], src, 1) == "pred", "pred")
    elif mode == "having":
        need(1 <= len(sel) <= 3 and c["value"] is None, "having shape")
        for s in sel:
            need(kind(s, "group", gb, src, 1) != "pred", "select pred")
        if not gb:
            need('"agg"' in json.dumps(sel), "no aggregate")
        need(kind(c["predicate"], "group", gb, src, 1) == "pred", "pred")
    elif mode in LEGACY:
        need(sel == [], "select")
        if c["value"] is None:
            need(mode == "count", "value")
        else:
            need(kind(c["value"], "row", [], src, 1) == "num", "value numeric")
        need(kind(c["predicate"], "row", [], src, 1) == "pred", "pred")
    else:
        raise Invalid("mode")


def lit_sql(v):
    if v is None:
        return "NULL"
    if is_int(v):
        return "(%d)" % v
    return "CAST(X'%s' AS TEXT)" % v.encode().hex() if v else "''"


def sql(e):
    op = e[0]
    if op == "col":
        return "%s.%s" % (e[1], e[2])
    if op == "lit":
        return lit_sql(e[1])
    if op in ("add", "sub"):
        return "(%s%s%s)" % (sql(e[1]), "+" if op == "add" else "-", sql(e[2]))
    if op in CMP:
        return "(%s %s %s)" % (sql(e[1]), CMP[op], sql(e[2]))
    if op in ("and", "or"):
        return "(%s %s %s)" % (sql(e[1]), op.upper(), sql(e[2]))
    if op == "not":
        return "(NOT %s)" % sql(e[1])
    if op == "isnull":
        return "(%s IS NULL)" % sql(e[1])
    if op == "agg":
        return "%s(%s)" % (e[1], "*" if e[2] is None else sql(e[2]))
    raise ValueError(op)


FROM = {"single": "t", "inner": "t JOIN u ON t.k=u.k", "left": "t LEFT JOIN u ON t.k=u.k"}


def reference(c):
    mode, gb = c["mode"], c["group_by"]
    w = sql(c["where"]) if c["where"] is not None else None
    p = sql(c["predicate"])
    out = []
    for i, f in enumerate([None, p, "NOT %s" % p, "(%s) IS NULL" % p]):
        if mode in ("rows", "distinct", "having"):
            cols = [sql(s) for s in c["select"]]
        elif mode == "group":
            cols = [sql(g) for g in gb]
        else:
            arg = "*" if c["value"] is None else sql(c["value"])
            cols = [sql(g) for g in gb]
            if i and mode in ("sum", "avg"):
                cols += ["sum(%s)" % arg, "count(%s)" % arg]
            else:
                cols.append("%s(%s)" % (mode, arg))
        q = "SELECT %s%s FROM %s" % ("DISTINCT " if mode == "distinct" else "", ",".join(cols),
                                     FROM[c["source"]])
        conds = [x for x in [w, f if mode != "having" else None] if x]
        if conds:
            q += " WHERE " + " AND ".join("(%s)" % x for x in conds)
        if gb and mode not in ("rows", "distinct"):
            q += " GROUP BY " + ",".join(sql(g) for g in gb)
        if mode == "having" and f:
            q += " HAVING " + f
        out.append(q)
    return out


def make_db(tables):
    db = sqlite3.connect(":memory:")
    for name in ("t", "u"):
        db.execute("CREATE TABLE %s(id INTEGER,k INTEGER,v INTEGER,tag TEXT)" % name)
        db.executemany("INSERT INTO %s VALUES(?,?,?,?)" % name, [tuple(r) for r in tables[name]])
    return db


def canon(rows):
    return sorted(repr([(type(x).__name__, x) for x in r]) for r in rows)


def mutate(tables, rnd):
    new = {}
    for name, rows in tables.items():
        rows = [list(r) for r in rows]
        for r in rows:
            for j in range(3):
                if rnd.random() < 0.3:
                    r[j] = rnd.choice([None, rnd.randint(-5, 5)])
            if rnd.random() < 0.2:
                r[3] = rnd.choice([None, "a", "b", "q'", ""])
        if rnd.random() < 0.5:
            rows.append([rnd.choice([None, 1, 2]), rnd.randint(-2, 2), rnd.randint(-3, 3), "a"])
        new[name] = rows
    return new


def semantic(c, plan, rnd):
    ref = reference(c)
    mine = [plan["base"]] + plan["parts"]
    for tables in (c["tables"], mutate(c["tables"], rnd), mutate(c["tables"], rnd), {"t": [], "u": []}):
        db = make_db(tables)
        for q, r in zip(mine, ref):
            a = db.execute(q["sql"], q["params"]).fetchall()
            b = db.execute(r).fetchall()
            if canon(a) != canon(b):
                return False, (q, r, a, b)
    return True, None


def strip(e, cols=True):
    if isinstance(e, list):
        if e and e[0] == "lit":
            return ["lit"]
        if e and e[0] == "col":
            return ["col", e[1], e[2]] if cols else ["col"]
        return [strip(x, cols) for x in e]
    return e


def fingerprint(c, cols=True):
    return json.dumps({k: strip(v, cols) for k, v in c.items() if k not in ("tables", "version")},
                      sort_keys=True)


def depth(e):
    kids = [x for x in e[1:] if isinstance(x, list)] if e[0] not in ("col", "lit") else []
    return 1 + max((depth(x) for x in kids), default=0)


def ops(e, acc, stage):
    if isinstance(e, list) and e and isinstance(e[0], str):
        acc["%s@%s" % (e[0], stage)] += 1
        if e[0] == "agg":
            acc["agg:%s:%s@%s" % (e[1], "star" if e[2] is None else "expr", stage)] += 1
        if e[0] == "col":
            acc["table:%s" % e[1]] += 1
            acc["column:%s" % e[2]] += 1
        if e[0] != "lit":
            for x in e[1:]:
                ops(x, acc, stage)


def main():
    rnd = random.Random(int(sys.argv[2]) if len(sys.argv) > 2 else 20261022)
    inputs = [bytes(rnd.getrandbits(8) for _ in range(rnd.randint(16, 512))) for _ in range(1024)]
    boundary = [b"", b"\0", b"\xff" * 512, bytes(range(256)) * 2, b"\0" * 513, b"A" * 1000]
    answers = run([{"op": "inspect", "hex": b.hex()} for b in inputs + boundary])
    bad = sem_bad = 0
    for a in answers:
        try:
            validate(a["case"])
        except Invalid as e:
            bad += 1
            if bad < 5:
                print("INVALID", e, json.dumps(a["case"])[:400])
        assert a["result"]["equivalent"] and a["result"]["calls"] == 4
        ok, info = semantic(a["case"], a["plan"], rnd)
        if not ok:
            sem_bad += 1
            if sem_bad < 5:
                print("SEMANTIC MISMATCH", info)
    print("schema invalid:", bad, "semantic mismatches:", sem_bad, "of", len(answers))
    cases = [a["case"] for a in answers[:1024]]
    print("modes", dict(Counter(c["mode"] for c in cases)))
    print("sources", dict(Counter(c["source"] for c in cases)))
    print("existing where", sum(c["where"] is not None for c in cases))
    print("grouped legacy", sum(c["mode"] in LEGACY and bool(c["group_by"]) for c in cases))
    print("distinct cases", len({json.dumps(c, sort_keys=True) for c in cases}))
    print("distinct dbs", len({json.dumps(c["tables"], sort_keys=True) for c in cases}))
    print("structural fp", len({fingerprint(c) for c in cases}))
    print("topology fp", len({fingerprint(c, False) for c in cases}))
    per = defaultdict(set)
    for c in cases:
        per[c["mode"]].add(fingerprint(c, False))
    print("topology per mode", {m: len(s) for m, s in per.items()})

    all3 = nonempty = empty_row = overlap = dup_having = allnull = 0
    for c in cases:
        db = make_db(c["tables"])
        ref = reference(c)
        base = db.execute(ref[0]).fetchall()
        nonempty += bool(base)
        p = sql(c["predicate"])
        w = sql(c["where"]) if c["where"] else "1"
        fs = (p, "NOT " + p, "(%s) IS NULL" % p)
        if c["mode"] == "having":
            gb = ",".join(sql(g) for g in c["group_by"])
            counts = [len(db.execute("SELECT 1 FROM %s WHERE %s %s HAVING %s" % (
                FROM[c["source"]], w, ("GROUP BY " + gb) if gb else "", f)).fetchall()) for f in fs]
            dup_having += len(base) != len(set(base))
        else:
            counts = [db.execute("SELECT count(*) FROM %s WHERE (%s) AND (%s)" % (
                FROM[c["source"]], w, f)).fetchone()[0] for f in fs]
            empty_row += db.execute("SELECT count(*) FROM %s WHERE %s" % (
                FROM[c["source"]], w)).fetchone()[0] == 0
        all3 += all(counts)
        if c["mode"] == "group":
            parts = [set(db.execute(q).fetchall()) for q in ref[1:]]
            overlap += any(parts[i] & parts[j] for i in range(3) for j in range(i + 1, 3))
        if c["mode"] in ("sum", "avg", "min", "max"):
            vals = db.execute("SELECT %s FROM %s WHERE %s" % (sql(c["value"]), FROM[c["source"]], w)).fetchall()
            allnull += bool(vals) and all(v[0] is None for v in vals)
    print("all3 partitions", all3, "nonempty base", nonempty, "empty row-stage", empty_row,
          "group overlap", overlap, "having dup", dup_having, "all-null agg input", allnull)

    acc = Counter()
    deep = 0
    for c in cases:
        hv = c["mode"] == "having"
        ops(c["predicate"], acc, "group" if hv else "row")
        deep += depth(c["predicate"]) >= 3
        if c["where"]:
            ops(c["where"], acc, "row")
            deep += depth(c["where"]) >= 3
        for s in c["select"]:
            ops(s, acc, "group" if hv else "row")
        for g in c["group_by"]:
            ops(g, acc, "row")
        if c["value"] is not None:
            ops(c["value"], acc, "row")
    print("depth>=3 predicates", deep)
    print("count(*) legacy", sum(c["mode"] == "count" and c["value"] is None for c in cases),
          "count(expr) legacy", sum(c["mode"] == "count" and c["value"] is not None for c in cases))
    print("ops", dict(sorted(acc.items())))

    base_inputs = [bytes(rnd.getrandbits(8) for _ in range(128)) for _ in range(64)]
    reqs = [{"op": "inspect", "hex": b.hex()} for b in base_inputs]
    variants = []
    for b in base_inputs:
        for q in range(4):
            nb = bytearray(b)
            nb[q * 32:(q + 1) * 32] = bytes(rnd.getrandbits(8) for _ in range(32))
            variants.append({"op": "inspect", "hex": bytes(nb).hex()})
    res = run(reqs + variants)
    orig, var = res[:64], res[64:]
    for q in range(4):
        ch = topo = 0
        for i in range(64):
            a, b = orig[i]["case"], var[i * 4 + q]["case"]
            ch += a != b
            topo += fingerprint(a, False) != fingerprint(b, False)
        print("quarter", q, "case changes", ch, "topology changes", topo)
    again = run(reqs[:16])
    assert all(x == y for x, y in zip(again, orig[:16])), "nondeterministic"
    print("deterministic ok")


main()

